using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Threading;
using System.Windows.Forms;
namespace MacroExecute
{
    internal static class WorkbenchInteractionTests
    {
        private static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
        private static IEnumerable<Control> All(Control parent){foreach(Control child in parent.Controls){yield return child;foreach(var nested in All(child))yield return nested;}}
        private static void Click(Control control){typeof(Control).GetMethod("OnClick",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(control,new object[]{EventArgs.Empty});}
        private static Macro Sample(){return new Macro{Steps=new List<Step>{new Step{Kind=ActionKind.Note,Text="first"},new Step{Kind=ActionKind.IfClipboard,Text="match"},new Step{Kind=ActionKind.Note,Text="inside"},new Step{Kind=ActionKind.Else},new Step{Kind=ActionKind.Note,Text="otherwise"},new Step{Kind=ActionKind.EndIf},new Step{Kind=ActionKind.Note,Text="last"}}};}
        public static void Run(Action<string,Action> test,string directory)
        {
            test("Noncontiguous selection preserves order and expands nested blocks once",delegate{var source=Sample();var result=SequenceSelection.Extract(source,new[]{6,1,2,1},directory);Check(result.Steps.Count==6&&result.Steps[0].Kind==ActionKind.IfClipboard&&result.Steps.Last().Text=="last","Selection order or block expansion failed");result.Steps[1].Text="edited";Check(source.Steps[2].Text=="inside","Selection aliases source");});
            test("Incomplete selected control flow and missing jump targets are rejected",delegate{foreach(var indices in new[]{new[]{3},new[]{5},new[]{2,3}}){bool rejected=false;try{SequenceSelection.Extract(Sample(),indices,directory);}catch(InvalidDataException){rejected=true;}Check(rejected,"Orphaned boundary accepted");}var macro=new Macro{Steps=new List<Step>{new Step{Kind=ActionKind.Label,Text="start"},new Step{Kind=ActionKind.Jump,Text="start"}}};try{SequenceSelection.Extract(macro,new[]{1},directory);throw new Exception("Missing target accepted");}catch(InvalidDataException){}});
            test("Selection paste renames colliding labels and remaps internal jumps",delegate{var macro=new Macro{Steps=new List<Step>{new Step{Kind=ActionKind.Label,Text="start"},new Step{Kind=ActionKind.Note}}};var payload=new Macro{Steps=new List<Step>{new Step{Kind=ActionKind.Label,Text="start"},new Step{Kind=ActionKind.Jump,Text="start"}}};var inserted=SequenceSelection.Insert(macro,payload,2,directory);Check(inserted[2].Text!="start"&&inserted[2].Text==inserted[3].Text&&payload.Steps[0].Text=="start","Label remapping changed original or lost jump");});
            test("Save selection keeps external references anchored to the source directory",delegate{string child=Path.Combine(directory,"selection-child.mexec");Storage.Save(child,new Macro{Steps=new List<Step>{new Step{Kind=ActionKind.Note}}});var source=new Macro{Steps=new List<Step>{new Step{Kind=ActionKind.Include,Target="selection-child.mexec"},new Step{Kind=ActionKind.CopyFile,Target="in.txt",Text="out.txt"}}};var selected=SequenceSelection.Extract(source,new[]{0,1},directory);Check(Path.IsPathRooted(selected.Steps[0].Target)&&selected.Steps[1].Text==Path.Combine(directory,"out.txt"),"Moved export broke relative dependencies");string path=Path.Combine(directory,"selected-workflow.mexec");Storage.Save(path,selected);Check(Storage.Load(path).Steps.Count==2&&source.Steps[0].Target=="selection-child.mexec","Export modified source");});
            test("Multi-row clipboard payload pastes atomically and Undo restores source",delegate{var context=SynchronizationContext.Current;try{using(var form=new MainForm(Sample(),null,false,false,true)){HeadlessUi.Render(form,Path.Combine(directory,"multi-selection.png"));form.SelectRowsHeadless(0,6);string payload=form.CopyRowsHeadless();Check(Storage.Decode(payload).Steps.Select(s=>s.Text).SequenceEqual(new[]{"first","last"}),"Wrong clipboard payload");string before=Storage.Encode(form.DocumentHeadless());form.PasteRowsHeadless(payload);Check(form.DocumentHeadless().Steps.Count==9,"Paste lost selected rows");Click(All(form).OfType<Button>().Single(b=>b.AccessibleName.Contains("Undo")));Check(Storage.Encode(form.DocumentHeadless())==before,"Undo failed to restore transaction");form.SelectRowsHeadless(0,1,6);Check(All(form).OfType<Button>().Single(b=>b.AccessibleName=="Duplicate block").Enabled,"Duplicate selection disabled");Check(!All(form).OfType<Button>().Single(b=>b.AccessibleName=="Edit settings…").Enabled,"Single editor remains active during multi-selection");HeadlessUi.Render(form,Path.Combine(directory,"selected-rows-aftershock.png"),true);Check(!form.Visible,"Selection test opened a window");}}finally{SynchronizationContext.SetSynchronizationContext(context);}});
            test("Multi-selection enable changes reject partial boundaries without editing the workflow",delegate{var context=SynchronizationContext.Current;try{using(var form=new MainForm(Sample(),null,false,false,true)){HeadlessUi.Render(form,Path.Combine(directory,"partial-toggle.png"));form.SelectRowsHeadless(0,5);string before=Storage.Encode(form.DocumentHeadless());bool rejected=false;try{typeof(MainForm).GetMethod("ToggleEnabled",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(form,null);}catch(System.Reflection.TargetInvocationException){rejected=true;}Check(rejected&&Storage.Encode(form.DocumentHeadless())==before,"Partial toggle corrupted control flow");}}finally{SynchronizationContext.SetSynchronizationContext(context);}});
            test("Toolbar prioritizes history and uses a named color-mode icon",delegate{using(var form=new MainForm(Sample(),null,false,false,true)){var buttons=All(form).OfType<Button>().ToArray();Check(!buttons.Any(b=>b.Text=="Open…"),"Open duplicated in toolbar");Check(buttons.Any(b=>b.AccessibleName=="Switch to light mode"&&b.Text==""&&b.Image!=null),"Color mode is not an accessible icon");Check(buttons.Any(b=>b.Text.Contains("Undo")&&(string)b.Tag=="primary")&&buttons.Any(b=>b.Text.Contains("Redo")&&(string)b.Tag=="selected"),"History controls lack accent");Check(All(form).OfType<ListView>().First().MultiSelect,"Sequence still single-select");}});
            test("Embedded editors stay in main window and restore controls on dismissal",delegate{var context=SynchronizationContext.Current;try{using(var owner=new MainForm(Sample(),null,false,false,true))using(var editor=new StepEditor(new Step{Kind=ActionKind.Delay},directory)){HeadlessUi.Render(owner,Path.Combine(directory,"dialog-owner.png"));var original=owner.Controls.Cast<Control>().ToDictionary(c=>c,c=>c.Enabled);using(InAppDialog.Attach(owner,editor)){Check(InAppDialog.IsOpen(owner)&&!editor.TopLevel&&editor.TopLevelControl==owner&&owner.OwnedForms.Length==0,"Editor detached from main window");Check(original.All(e=>!e.Key.Enabled),"Background editing not blocked");HeadlessUi.Render(owner,Path.Combine(directory,"embedded-step-editor.png"));Check(!owner.Visible&&!editor.Visible,"Embedded render showed a top-level window");using(var visibility=new CaptureVisibility(editor))Check(owner.Opacity==0,"Capture did not hide main app");Check(owner.Opacity==1,"Capture did not restore main app");}Check(!InAppDialog.IsOpen(owner)&&original.All(e=>e.Key.Enabled==e.Value),"Modal state or disabled controls leaked");}}finally{SynchronizationContext.SetSynchronizationContext(context);}});
            test("Embedded action Save and Cancel retain modal result and owner lifetime",delegate{var context=SynchronizationContext.Current;try{using(var owner=new MainForm(Sample(),null,false,false,true)){HeadlessUi.Render(owner,Path.Combine(directory,"modal-result-owner.png"));using(var editor=new StepEditor(new Step{Kind=ActionKind.Delay},directory))using(InAppDialog.Attach(owner,editor)){Click(All(editor).OfType<Button>().Single(b=>b.Text=="Save step"));Check(editor.DialogResult==DialogResult.OK&&!owner.IsDisposed,"Save did not finish the embedded editor");}Check(!InAppDialog.IsOpen(owner),"Save leaked modal state");using(var editor=new StepEditor(new Step{Kind=ActionKind.Delay},directory))using(InAppDialog.Attach(owner,editor)){editor.DialogResult=DialogResult.Cancel;Check(editor.DialogResult==DialogResult.Cancel&&!owner.IsDisposed,"Cancel closed owner");}Check(!InAppDialog.IsOpen(owner),"Cancel leaked modal state");}}finally{SynchronizationContext.SetSynchronizationContext(context);}});
            test("Sequence context menu stays embedded and preserves a multi-row selection",delegate{var context=SynchronizationContext.Current;try{using(var owner=new MainForm(Sample(),null,false,false,true)){HeadlessUi.Render(owner,Path.Combine(directory,"context-owner.png"));owner.SelectRowsHeadless(0,6);var list=All(owner).OfType<ListView>().First();var args=new System.ComponentModel.CancelEventArgs();typeof(ContextMenuStrip).GetMethod("OnOpening",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(list.ContextMenuStrip,new object[]{args});Check(args.Cancel&&All(owner).Any(c=>c.AccessibleName=="In-app navigation menu"),"Native context popup was not replaced");Check(list.SelectedIndices.Count==2,"Context menu lost multi-selection");InWindowMenu.Close(owner);}}finally{SynchronizationContext.SetSynchronizationContext(context);}});
            test("Top navigation renders inside the main window with keyboard-dismissable menus",delegate{var context=SynchronizationContext.Current;try{using(var owner=new MainForm(Sample(),null,false,false,true)){HeadlessUi.Render(owner,Path.Combine(directory,"menu-owner.png"));foreach(string name in new[]{"File","View","Settings"}){Click(All(owner).OfType<Button>().Single(b=>b.Text.StartsWith(name+" ")));var menu=All(owner).Single(c=>c.AccessibleName=="In-app navigation menu");Check(menu.TopLevelControl==owner&&owner.OwnedForms.Length==0,"Menu is a separate window");HeadlessUi.Render(owner,Path.Combine(directory,"embedded-menu-"+name+".png"));InWindowMenu.Close(owner);}Check(!All(owner).Any(c=>c.AccessibleName=="In-app navigation menu"),"Menu did not dispose");}}finally{SynchronizationContext.SetSynchronizationContext(context);}});
        }
    }
}
